"""Deterministic Bangla spacing normalizer for SSC Chemistry question-bank drafts."""
import re

_BN_LET = r"\u0980-\u09e3\u09f0-\u09ff"
_BN_RE = re.compile(f"[{_BN_LET}]+")
_HAS_BN_RE = re.compile(r"[\u0980-\u09ff]")
_IMG_URL_RE = re.compile(r"!\[[^\]]*\]\([^)]*\)|https?://\S+")
_BN_INIT = r"\u0985-\u09b9\u09ce\u09dc-\u09de\u09f0-\u09f1"
_HYP_BN_RE = re.compile(
    r"অ-ইলেকট্রোলাইট(?:ের|ে|কে|গুলো|গুলোর)?|(?<![\u0980-\u09ff])অ-[\u0980-\u09e3]+|H(?:উৎপাদ|বিক্রি[য়য়]ক)"
)
_HYP_CASE1_RE = re.compile(rf"(?<=[A-Za-z0-9₀-₉⁰-⁹⁺⁻°)\]])-(এর|কে|তে)(?=[{_BN_LET}]{{2,}})")
_HYP_CASE2_RE = re.compile(rf"(?<=[A-Za-z0-9₀-₉⁰-⁹⁺⁻°)\]])-(এ|র|য়)(?!র(?![{_BN_LET}]))(?=[{_BN_LET}]{{2,}})")
_DIGIT_CLF_RE = re.compile(
    rf"(?:([0-9০-৯]+)(টি|টির|টিতে|টা|টার|গুলো|গুলোর|গুলোতে)"
    rf"|(?<![0-9০-৯])(1|5|7|8|9|10|১|৫|৭|৮|৯|১০)(ম)"
    rf"|(?<![0-9০-৯])(2|3|২|৩)(য়)"
    rf"|(?<![0-9০-৯])(4|৪)(র্থ)"
    rf"|(?<![0-9০-৯])(6|৬)(ষ্ঠ)"
    rf"|(?<![0-9০-৯])(1[1-9]|20|১[১-৯]|২০)(শ))(?=[{_BN_INIT}])"
)
_LAT_TO_BN_RE = re.compile(rf"([A-Za-z₀-₉⁰-⁹⁺⁻])([{_BN_LET}])")
_DIG_TO_BN_RE = re.compile(
    rf"([0-9])(?!(?:টি|টির|টিতে|টা|টার|গুলো|গুলোর|গুলোতে|ম|য়|র্থ|ষ্ঠ|শ)(?![{_BN_LET}]))([{_BN_LET}])"
)
_BN_TO_LAT_RE = re.compile(rf"([{_BN_LET}])([A-Za-z0-9]|\([A-Z])")
_DANDA_RE = re.compile(r"।(?![\s।\n\"'\)\]\},;।]|$)")
_SEMI_RE = re.compile(rf";(?=[{_BN_LET}A-Za-z0-9])")
_QMARK_RE = re.compile(rf"\?(?=[{_BN_LET}A-Za-z])")
_COLON_RE = re.compile(rf":(?=[{_BN_LET}])")
_COMMA_RE = re.compile(rf"(?<=[^,\s]),(?=[{_BN_LET}])")
_MULTI_SP_RE = re.compile(r"[ \t]{2,}")

