def clean_chemistry_text(s: str) -> str:
    if not s or not isinstance(s, str):
        return s
    imgs: list[str] = []

    def _save_img(m: re.Match[str]) -> str:
        imgs.append(m.group(0))
        return f"@@IMG{len(imgs) - 1}@@"

    s = _IMG_URL_RE.sub(_save_img, s)

    hyps: list[str] = []

    def _save_hyp(m: re.Match[str]) -> str:
        hyps.append(m.group(0))
        return f"@@HYP{len(hyps) - 1}@@"

    s = _HYP_BN_RE.sub(_save_hyp, s)
    s = _HYP_CASE1_RE.sub(r"-\1 ", s)
    s = _HYP_CASE2_RE.sub(r"-\1 ", s)
    s = _DIGIT_CLF_RE.sub(lambda m: "".join(g for g in m.groups() if g) + " ", s)
    s = _LAT_TO_BN_RE.sub(r"\1 \2", s)
    s = _DIG_TO_BN_RE.sub(r"\1 \2", s)
    s = _BN_TO_LAT_RE.sub(r"\1 \2", s)
    s = _DANDA_RE.sub("। ", s)
    s = _SEMI_RE.sub("; ", s)
    s = _QMARK_RE.sub("? ", s)
    s = _COLON_RE.sub(": ", s)
    s = _COMMA_RE.sub(", ", s)
    s = _BN_RE.sub(lambda m: TOKEN_MAP.get(m.group(0), m.group(0)), s)

    for idx, h in enumerate(hyps):
        s = re.sub(rf"([{_BN_LET}])@@HYP{idx}@@", rf"\1 @@HYP{idx}@@", s)
        s = re.sub(rf"@@HYP{idx}@@(?=[{_BN_INIT}])", rf"@@HYP{idx}@@ ", s)
        s = s.replace(f"@@HYP{idx}@@", h)

    s = _MULTI_SP_RE.sub(" ", s)
    for idx, im in enumerate(imgs):
        s = s.replace(f"@@IMG{idx}@@", im)
    return s


def clean_chemistry_inputs(val):
    """Clean only Bangla-containing prose strings inside validation ledger inputs."""
    if isinstance(val, str):
        return clean_chemistry_text(val) if _HAS_BN_RE.search(val) else val
    if isinstance(val, dict):
        return {k: clean_chemistry_inputs(v) for k, v in val.items()}
    if isinstance(val, list):
        return [clean_chemistry_inputs(v) for v in val]
    return val
